import assert from "node:assert/strict";
import { test } from "vitest";
import { suggestNameFromEmail } from "@/lib/contacts/suggestNameFromEmail";

test("suggests every word from the local part without using the domain", () => {
  assert.equal(suggestNameFromEmail("[REDACTED_EMAIL]"), "Alex Morgan");
  assert.equal(
    suggestNameFromEmail("[REDACTED_EMAIL]"),
    "Jane Doe Smith",
  );
});

test("normalizes capitalization, repeated separators, and surrounding space", () => {
  assert.equal(
    suggestNameFromEmail("  [REDACTED_EMAIL]  "),
    "Alex Morgan",
  );
});

test("supports suggestions while an address is still being typed", () => {
  assert.equal(suggestNameFromEmail("alex.mor"), "Alex Mor");
  assert.equal(suggestNameFromEmail("alex@"), "Alex");
});

test("clearing the email produces an empty suggestion", () => {
  for (const email of ["", "  ", "@example.test", ".__-"]) {
    assert.equal(suggestNameFromEmail(email), "");
  }
});
